package com.englishcoach.reading.entity;

import jakarta.persistence.*;
import lombok.*;
import org.hibernate.annotations.CreationTimestamp;
import org.hibernate.annotations.UpdateTimestamp;

import java.time.Instant;

/**
 * Shared Contextual Explanation Cache.
 * Stores reusable, generic contextual explanations generated by AI / Dictionary.
 * Reusable across all users for extreme token optimization.
 */
@Entity
@Table(
    name = "reading_contextual_explanations",
    uniqueConstraints = {
        @UniqueConstraint(
            name = "uk_rce_mat_norm_hash_ver",
            columnNames = {"reading_material_id", "normalized_text", "context_hash", "explanation_version"}
        )
    },
    indexes = {
        @Index(
            name = "idx_rce_lookup",
            columnList = "reading_material_id, normalized_text, context_hash, explanation_version"
        )
    }
)
@Data
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class ReadingContextualExplanation {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "reading_material_id", nullable = false)
    private Long readingMaterialId;

    @Column(name = "selected_text", nullable = false)
    private String selectedText;

    @Column(name = "normalized_text", nullable = false)
    private String normalizedText;

    private String lemma;

    private String pos;

    private String ipa;

    private String cefr;

    private String frequency;

    @Column(name = "meaning_in_context", nullable = false, columnDefinition = "TEXT")
    private String meaningInContext;

    @Column(name = "native_explanation", columnDefinition = "TEXT")
    private String nativeExplanation;

    @Column(name = "source_sentence", nullable = false, columnDefinition = "TEXT")
    private String sourceSentence;

    @Column(name = "context_hash", nullable = false, length = 64)
    private String contextHash;

    @Column(name = "collocations_json", columnDefinition = "TEXT")
    private String collocationsJson;

    @Column(name = "synonyms_json", columnDefinition = "TEXT")
    private String synonymsJson;

    @Column(name = "grammar_note", columnDefinition = "TEXT")
    private String grammarNote;

    @Builder.Default
    @Column(name = "explanation_version", nullable = false, length = 50)
    private String explanationVersion = "v1";

    @CreationTimestamp
    @Column(name = "created_at", nullable = false, updatable = false)
    private Instant createdAt;

    @UpdateTimestamp
    @Column(name = "updated_at", nullable = false)
    private Instant updatedAt;
}
